<style scoped lang="scss" src="./table.scss"></style>

<script>
import { Component, Prop, Vue } from "vue-property-decorator";
import {
  TableCellAlignment,
  TableDataType,
  TableCellStatus,
  TableCellSize,
  TableMode
} from "./table.constants";
import TableCell from "../../components/table-cell/table-cell";
import TableHeaderCell from "../../components/table-header-cell/table-header-cell";
import { isBefore } from "date-fns";
import { CurrencyNotation, CurrencyNotationValues } from "../constants";
import { has } from "../../util/has";
import TablePageIndicator from "../../components/table-page-indicator/table-page-indicator";
import Select from "../../components/select/select";
import SelectionMenu from "../../components/selection-menu/selection-menu";
import {
  TableHeaderCellAlignment,
  TableHeaderMode,
  TableSortMode
} from "../table-header-cell/table-header-cell.constants";
import Button from "../../components/button/button";
import { TableRowMode } from "../table-cell/table-cell.constants";

function compareByType(a, b, type, assending = TableSortMode.ASCENDING) {
  if (assending === TableSortMode.NO_SORT) return 0;

  if (type === TableDataType.NAME) {
    const fullNameA = `${a.firstName} ${a.lastName}`;
    const fullNameB = `${b.firstName} ${b.lastName}`;

    return assending === TableSortMode.DESCENDING
      ? fullNameB.localeCompare(fullNameA)
      : fullNameA.localeCompare(fullNameB);
  }

  if (type === TableDataType.STRING) {
    return assending === TableSortMode.DESCENDING
      ? b.localeCompare(a)
      : a.localeCompare(b);
  }

  if (type === TableDataType.NUMBER) {
    return assending === TableSortMode.DESCENDING ? b - a : a - b;
  }

  if (type === TableDataType.MONEY) {
    return assending === TableSortMode.DESCENDING
      ? b.amount - a.amount
      : a.amount - b.amount;
  }

  if (type === TableDataType.DATE) {
    const asc = assending === TableSortMode.DESCENDING ? 1 : -1;
    return isBefore(a, b) ? asc : -asc;
  }

  if (type === TableDataType.STATUS) {
    return assending === TableSortMode.DESCENDING
      ? b.localeCompare(a)
      : a.localeCompare(b);
  }

  if (type === TableDataType.SELECT) {
    return assending === TableSortMode.DESCENDING
      ? b.localeCompare(a)
      : a.localeCompare(b);
  }

  return 0;
}

function filterByType(data, type, condition) {
  if (!condition) return true;

  if (type === TableDataType.NAME) {
    const fullName = `${data.firstName} ${data.lastName}`;

    return fullName.toLowerCase().indexOf(condition.toLowerCase()) >= 0;
  }

  if (type === TableDataType.STRING) {
    return data.toLowerCase().indexOf(condition.toLowerCase()) >= 0;
  }

  if (type === TableDataType.NUMBER) {
    return data.toString().indexOf(condition) >= 0;
  }

  if (type === TableDataType.MONEY) {
    return data.amount.toString().indexOf(condition) >= 0;
  }

  if (type === TableDataType.DATE) {
    return data.toISOString().indexOf(condition) >= 0;
  }

  if (type === TableDataType.SELECT || type === TableDataType.STATUS) {
    return data.toLowerCase().indexOf(condition.toLowerCase()) >= 0;
  }
}

const headerAlignToCellAlign = {
  [TableHeaderCellAlignment.LEFT]: TableCellAlignment.LEFT,
  [TableHeaderCellAlignment.CENTER]: TableCellAlignment.CENTER,
  [TableHeaderCellAlignment.RIGHT]: TableCellAlignment.RIGHT
};

const modeToHeaderMode = {
  [TableMode.DEFAUTL]: TableHeaderMode.DEFAULT,
  [TableMode.GMS_SCHEDULE]: TableHeaderMode.GMS_SCHEDULE,
  [TableMode.GMS_TRANSACTION]: TableHeaderMode.GMS_TRANSACTION
};

const modeToRowMode = {
  [TableMode.DEFAUTL]: TableRowMode.DEFAULT,
  [TableMode.GMS_SCHEDULE]: TableRowMode.GMS_SCHEDULE,
  [TableMode.GMS_TRANSACTION]: TableRowMode.GMS_TRANSACTION
};

const modeToRowsClass = {
  [TableMode.DEFAUTL]: "Table__Rows",
  [TableMode.GMS_SCHEDULE]: "Table__Rows--gms_schedule",
  [TableMode.GMS_TRANSACTION]: "Table__Rows--gms_transaction"
};

@Component({
  components: {
    TablePageIndicator,
    Select,
    SelectionMenu,
    TableHeaderCell,
    TableCell,
    Button
  }
})
export default class Table extends Vue {
  /**
   * Defines the columns of the table and sets their header information.
   *
   * {
   *   // Label for the header
   *   name: String,
   *   // Identifier used by row data to place a cell within the column
   *   id: String,
   *   // The data type of the column
   *   type: TableDataType,
   *   // Alignment of elements in the column
   *   align: TableHeaderCellAlignment,
   *   // The cell size of the column
   *   size: TableCellSize,
   *   // Rendering mode of the cells
   *   mode: TableCellMode,
   *   // Indicates if the column can be sorted or not. Defaults to true
   *   sortable: Boolean
   * },
   */
  @Prop({
    type: Array,
    default: () => []
  })
  headers;

  @Prop({
    type: Array,
    default: () => []
  })
  rows;

  @Prop({
    type: String,
    default: CurrencyNotation.USD,
    validator: has(CurrencyNotationValues)
  })
  currency;

  @Prop({
    type: Boolean,
    default: false
  })
  enableFilter;

  @Prop({
    type: String,
    default: ""
  })
  searchValue;

  @Prop({
    type: Object,
    default: () => {
      return {
        label: "",
        value: ""
      };
    }
  })
  period;

  @Prop({
    type: Boolean,
    default: true
  })
  showControls;

  @Prop({
    type: Boolean,
    default: false
  })
  stretch;

  @Prop({
    type: Boolean,
    default: true
  })
  hasBorder;

  @Prop({
    type: String,
    default: TableMode.DEFAUTL
  })
  mode;

  /**
   * The list of rows per page options.
   * Each option should include one label and its number value
   *
   * [
   *   label: string;
   *   value: number;
   * ]
   */
  @Prop({
    type: Array,
    default: () => []
  })
  rowsPerPageOptions;

  @Prop({
    type: Number,
    default: 10
  })
  defaultRowsPerPage;

  @Prop({ type: Boolean, default: false })
  isLoading;

  @Prop({ type: Boolean, default: false })
  multiFilter;

  @Prop({ type: Number, default: 10 })
  paginationLimit;

  currentPage = 0;
  scrollLeft = 0;
  clientWidth = 0;
  scrollWidth = 0;
  showRightEdge = false;
  marginRight = 64;
  minWidth = 0;
  hovered = false;

  filters = new Map();
  currentRows = [];
  currentPageRows = [];

  currentRowsPerPage = 10;
  TableDataType = TableDataType;
  TableSortMode = TableSortMode;
  wasEnabledFilter = false;

  sortId = void 0;
  sortType = void 0;
  sortMode = TableSortMode.NO_SORT;
  sortFunc = void 0;

  beforeMount() {
    for (let i = 0; i < this.headers.length; i++) {
      const header = this.headers[i];
      const filterOptions = header.filterOptions || [];

      if (filterOptions) {
        for (let j = 0; j < filterOptions.length; j++) {
          filterOptions[j].selected = true;
        }
      }

      this.filters.set(header.id, {
        searchWord: "",
        options: filterOptions
      });
    }

    this.currentRowsPerPage = this.defaultRowsPerPage;
    this.currentRows = this.rows;
    this.getCurrentPageRows();
  }

  mounted() {
    window.addEventListener("resize", this.handleResize);
    window.addEventListener("scroll", this.handleScroll);

    for (let i = 0; i < this.headers.length; i++) {
      switch (this.headers[i].size) {
        case TableCellSize.SMALL:
          this.minWidth += 100;
          break;
        case TableCellSize.MEDIUM:
          this.minWidth += 120;
          break;
        case TableCellSize.LARGE:
          this.minWidth += 220;
          break;
        default:
          break;
      }
    }

    this.checkRightEdge();
  }

  beforeUpdate() {
    this.getCurrentRows();
  }

  updated() {
    if (this.wasEnabledFilter !== this.enableFilter) {
      // this.getCurrentRows();
      this.wasEnabledFilter = this.enableFilter;
    }

    // this.getCurrentRows();
  }

  checkRightEdge() {
    if (this.$refs.table) {
      this.scrollLeft = this.$refs.table.scrollLeft;
      this.clientWidth = this.$refs.table.clientWidth;
      this.scrollWidth = this.$refs.table.scrollWidth;

      this.showRightEdge =
        this.clientWidth < this.minWidth &&
        this.clientWidth + this.scrollLeft <= this.scrollWidth - 1;
    }
  }

  handleScroll() {
    this.checkRightEdge();
  }

  handleResize() {
    this.checkRightEdge();

    if (this.$refs.table) {
      if (this.minWidth < this.clientWidth + this.scrollLeft) {
        this.$refs.table.scrollLeft = Math.max(
          0,
          this.minWidth - this.clientWidth
        );
      }
    }

    if (this.$refs.tableContainer) {
      const containerWidth = this.$refs.tableContainer.clientWidth;

      this.marginRight = Math.min(
        Math.max(containerWidth - this.minWidth - 64, 0),
        64
      );
    }
  }

  getCellAlignment(align) {
    return headerAlignToCellAlign[align];
  }

  getAlignClass(align) {
    return align;
  }

  getHeaderSizeClass(size) {
    if (this.rows && this.rows.length > 0) {
      return size;
    }

    return `${size}Empty`;
  }

  getEmptySizeClass(size) {
    return `${size}Empty`;
  }

  get headerMode() {
    return modeToHeaderMode[this.mode];
  }

  get rowMode() {
    return modeToRowMode[this.mode];
  }

  get rowsClass() {
    return modeToRowsClass[this.mode];
  }

  get paddingStyle() {
    if (this.stretch) {
      return {};
    }

    return {
      padding: `0px ${this.marginRight}px 0px 64px`
    };
  }

  get maskStyle() {
    return {
      opacity: this.hovered ? 0 : 1,
      left: `${this.scrollLeft}px`
    };
  }

  get upperStyle() {
    if (this.rows && this.rows.length > 0) {
      return {};
    }

    return {
      overflow: "hidden"
    };
  }

  isWarning(row) {
    const status = row.data["status"];
    return row.warning || (status && status === TableCellStatus.FAILED);
  }

  isExpired(row) {
    const status = row.data["status"];
    return status && status === TableCellStatus.EXPIRED;
  }

  get hasContent() {
    return (
      this.rows &&
      this.rows.length > 0 &&
      this.headers.filter(header => header.display === void 0 || header.display)
        .length > 0
    );
  }

  getCellData(row, id) {
    return row.data[id];
  }

  getImageSrc(row, id) {
    if (row.data[id]) {
      return row.data[id].image;
    }

    return "";
  }

  getSearchDefaultValue(header) {
    const filter = this.filters.get(header.id);

    if (filter && filter.searchWord) {
      return filter.searchWord;
    }

    return "";
  }

  getAllIsSelected(header) {
    const filter = this.filters.get(header.id);
    return filter && filter.options.find(o => o.selected === false) === void 0;
  }

  handleSendMessage(index, id) {
    const i = this.currentPage * this.currentRowsPerPage + index;
    console.warn(`Send Message to ${this.rows[i].data[id].donor}`);
    this.$emit("onSendMessage", i);
  }

  handleThankDonor(index, id) {
    const i = this.currentPage * this.currentRowsPerPage + index;
    if (this.rows[i].data[id].thanked !== undefined)
      this.rows[i].data[id].thanked = true;
    this.$emit("onThankDonor", i);
  }

  handlePageChange(index) {
    this.currentPage = index;
    this.getCurrentPageRows();
  }

  handleSelectionChange(value) {
    this.currentRowsPerPage = value;
    const totalPage = Math.ceil(this.rows.length / this.currentRowsPerPage);
    this.currentPage = Math.min(totalPage - 1, this.currentPage);
    this.getCurrentPageRows();
  }

  handleInput(value, header) {
    if (header) {
      const filter = this.filters.get(header.id);

      if (filter) {
        if (value) {
          filter.searchWord = value;
        } else {
          filter.searchWord = "";
        }
      }

      this.getCurrentRows();
    }
  }

  focusOnId(id) {
    if (!this.multiFilter) {
      this.filters.forEach((filter, key) => {
        if (key !== id) {
          filter.options.forEach(option => {
            if (!option.selected) option.selected = true;
          });

          filter.searchWord = "";
        }
      });
    }
  }

  handleSelectOption(optionIndex, header) {
    if (header) {
      const filter = this.filters.get(header.id);
      this.focusOnId(header.id);

      if (filter) {
        const selected = filter.options[optionIndex].selected;
        filter.options[optionIndex].selected = !selected;
      }

      this.getCurrentRows();
    }
  }

  getFilterOptions(header) {
    if (header) {
      const filter = this.filters.get(header.id);

      if (filter && filter.options && filter.options.length > 0) {
        return filter.options;
      }
    }

    return [];
  }

  showRow(row) {
    if (!this.searchValue && !(this.period && this.period.filter)) return true;
    const displayHeaders = this.headers.filter(header => header.display);

    for (let i = 0; i < displayHeaders.length; i++) {
      const id = displayHeaders[i].id;
      const type = displayHeaders[i].type;

      if (filterByType(row.data[id], type, this.searchValue)) return true;
    }

    return false;
  }

  getCurrentRows() {
    const displayHeaders = this.headers.filter(header => header.display);

    // Filters
    let currentItems = this.rows.slice(0);

    // Period filter
    if (this.period && this.period.filter) {
      currentItems = currentItems.filter(row =>
        this.period.filter(row.data.date)
      );
    }

    // Global search word
    if (this.searchValue) {
      currentItems = currentItems.filter(row => {
        for (let i = 0; i < displayHeaders.length; i++) {
          const id = displayHeaders[i].id;
          const type = displayHeaders[i].type;

          if (filterByType(row.data[id], type, this.searchValue)) return true;
        }
      });
    }

    if (this.enableFilter) {
      for (let i = 0; i < displayHeaders.length; i++) {
        const id = displayHeaders[i].id;
        const type = displayHeaders[i].type;
        const filter = this.filters.get(id);

        // Search Word
        if (filter && filter.searchWord) {
          const searchWord = filter.searchWord;
          currentItems = currentItems.filter(
            item =>
              filterByType(item.data[id], type, searchWord) ||
              !this.enableFilter
          );
        }

        // Filters
        if (filter && filter.options && filter.options.length > 0) {
          const options = filter.options;
          currentItems = currentItems.filter(item => {
            if (!this.enableFilter) return true;
            let result = false;

            options.forEach(option => {
              if (option.selected) {
                if (option.value && option.value === item.data[id]) {
                  result = true;
                }

                if (option.filterFunc) {
                  if (option.filterFunc(item.data[id])) result = true;
                }
              }
            });

            return result;
          });
        }
      }
    }

    // Sort
    if (this.sortId && this.sortType) {
      const id = this.sortId;
      const type = this.sortType;

      currentItems.sort((a, b) => {
        const data1 = a.data[id];
        const data2 = b.data[id];

        if (this.sortMode === TableSortMode.CUSTOMIZE) {
          return this.sortFunc ? this.sortFunc(data1, data2) : 0;
        }

        return compareByType(data1, data2, type, this.sortMode);
      });
    }

    this.currentRows = currentItems;

    // Page
    this.getCurrentPageRows();
  }

  getCurrentPageRows() {
    this.currentPage = Math.min(
      this.currentPage,
      Math.ceil(this.currentRows.length / this.currentRowsPerPage)
    );

    this.currentPageRows = this.currentRows.filter((_item, index) => {
      const start = this.currentPage * this.currentRowsPerPage;
      const end = (this.currentPage + 1) * this.currentRowsPerPage;
      return index >= start && index < end;
    });
  }

  get displayedHeaders() {
    return this.headers.filter(
      header => header.display === void 0 || header.display === true
    );
  }

  handleSelectAll(header) {
    const filter = this.filters.get(header.id);
    this.focusOnId(header.id);

    if (filter) {
      for (let i = 0; i < filter.options.length; i++) {
        filter.options[i].selected = true;
      }

      this.getCurrentRows();
    }
  }

  handleClear(header) {
    const filter = this.filters.get(header.id);
    this.focusOnId(header.id);

    if (filter) {
      for (let i = 0; i < filter.options.length; i++) {
        filter.options[i].selected = false;
      }

      this.getCurrentRows();
    }
  }

  getSortOptions(header) {
    if (header) {
      return header.sortOptions;
    }

    return [];
  }

  handleSort(option, header) {
    this.sortId = header.id;
    this.sortType = header.type;
    this.sortMode = option.mode;
    this.sortFunc = option.compare;

    this.getCurrentRows();
  }

  handleSortIncrease(header) {
    const id = header.id;
    this.sortId = header.id;
    this.sortType = header.type;
    this.sortMode = TableSortMode.ASCENDING;

    this.currentRows = this.currentRows.sort((a, b) => {
      const data1 = a.data[id];
      const data2 = b.data[id];

      return compareByType(data1, data2, header.type, TableSortMode.ASCENDING);
    });
    this.getCurrentPageRows();
    this.$forceUpdate();
  }

  handleSortDecrease(header) {
    const id = header.id;
    this.sortId = id;
    this.sortType = header.type;
    this.sortMode = TableSortMode.DESCENDING;

    this.currentRows.sort((a, b) => {
      const data1 = a.data[id];
      const data2 = b.data[id];

      return compareByType(data1, data2, header.type, TableSortMode.DESCENDING);
    });
    this.getCurrentPageRows();
    this.$forceUpdate();
  }

  handleMouseOver() {
    this.hovered = true;
  }

  handleMouseOut() {
    this.hovered = false;
  }
}
</script>

<template>
  <div class="Table" ref="tableContainer" :style="paddingStyle">
    <div
      class="Table__Upper"
      ref="table"
      @mouseover="handleMouseOver"
      @mouseout="handleMouseOut"
      @scroll="handleScroll"
      :style="upperStyle"
    >
      <div class="Table__Header">
        <TableHeaderCell
          v-for="(header, index) of displayedHeaders"
          :class="[
            'PaginationTable__HeaderCell',
            getHeaderSizeClass(header.size),
            getAlignClass(header.align)
          ]"
          :key="index"
          :name="header.name"
          :mode="headerMode"
          :size="header.size"
          :align="header.align"
          :enableFilter="header.sortable && enableFilter"
          :filterOptions="getFilterOptions(header)"
          :sortOptions="getSortOptions(header)"
          :disable="!hasContent"
          :searchDefaultValue="getSearchDefaultValue(header)"
          :allIsSelected="getAllIsSelected(header)"
          :hasBorder="hasBorder"
          @selectAll="handleSelectAll(header)"
          @clear="handleClear(header)"
          @selectOption="handleSelectOption($event, header)"
          @input="handleInput($event, header)"
          @sort="handleSort($event, header)"
          @onSortIncrease="handleSortIncrease(header)"
          @onSortDecrease="handleSortDecrease(header)"
        />
      </div>
      <div v-if="isLoading" class="Table__LoaderContainer">
        <div class="Table__Loader" />
      </div>
      <div v-else>
        <div v-if="hasContent" :key="searchValue" class="Table__Content">
          <div :class="rowsClass" v-for="(row, i) of currentPageRows" :key="i">
            <div class="Table__Row">
              <TableCell
                :class="[
                  'Table__RowCell',
                  i % 2 === 1 ? 'Table--odd_row' : 'Table--even_row'
                ]"
                v-for="(header, j) of displayedHeaders"
                :key="`${i}_${j}`"
                :type="header.type"
                :align="getCellAlignment(header.align)"
                :size="header.size"
                :mode="header.mode"
                :rowMode="rowMode"
                :hasBorder="hasBorder"
                :data="getCellData(row, header.id)"
                :warning="isWarning(row)"
                :expired="isExpired(row)"
                :options="header.options"
                :imageSrc="getImageSrc(row, header.id)"
                @onSendMessage="handleSendMessage(i, header.id)"
                @onThankDonor="handleThankDonor(i, header.id)"
              />
            </div>
          </div>
        </div>
        <div v-if="hasContent" class="Table__Mask" :style="maskStyle">
          <transition name="fade">
            <div v-if="showRightEdge" class="Table__RightEdge" />
          </transition>
        </div>
      </div>
    </div>
    <div v-if="!hasContent" class="Table__EmptyContainer">
      <div class="Table__Empty">
        <div v-for="i in 11" :key="i" class="Table__EmptyRow">
          <div
            v-for="(header, index) of headers"
            :key="index"
            :class="['Table__EmptyCell', getEmptySizeClass(header.size)]"
          >
            <div class="Table__EmptyFill" />
          </div>
        </div>
      </div>
      <div class="Table__EmptyMask">
        <div class="Table__MainTitle">
          There is currently nothing to report.
        </div>
        <div class="Table__SubTitle">
          Your reports will populate once there is campaign activity.
        </div>
        <Button
          class="Table__ButtonCampaigns"
          label="Go to your Campaigns"
          @click="$emit('goToCampaigns')"
        />
      </div>
    </div>
    <div v-if="hasContent && showControls" class="Table__Controls">
      <div class="Table__ControlLeft">
        <div>Show</div>
        <div class="Table__Perpage">
          <Select
            class="RowsPerPageMenu"
            label="# Rows"
            :value="currentRowsPerPage"
            :items="rowsPerPageOptions"
            @select="handleSelectionChange"
          />
        </div>
        <div>per page</div>
      </div>
      <div
        v-if="this.currentRowsPerPage < this.currentRows.length"
        class="Table__ControlMiddle"
      >
        <TablePageIndicator
          :totalPageNumber="
            Math.ceil(this.currentRows.length / currentRowsPerPage)
          "
          :displayNumber="paginationLimit"
          @onChangePage="handlePageChange"
        />
      </div>
      <div
        class="Table__ControlRight"
        v-if="this.currentRowsPerPage < this.currentRows.length"
      >
        {{
          `Page ${this.currentPage + 1} of ${Math.ceil(
            this.currentRows.length / currentRowsPerPage
          )}`
        }}
      </div>
    </div>
  </div>
</template>
